// HAL validation for the production full-scene hyperspace refraction shader.
#define NOMINMAX
#include <windows.h>
#include <d3dx9.h>
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cmath>
static IDirect3DDevice9* D;static IDirect3DTexture9* Scene;static IDirect3DSurface9 *RT,*Read;
static IDirect3DVertexShader9* VS;static IDirect3DPixelShader9* PS;
static const int W=960,H=540;static std::vector<DWORD> Original;
static void Check(HRESULT R){if(FAILED(R)){printf("FAIL %08lx\n",R);exit(2);}}
static void Require(bool V,char const* S){printf("%s: %s\n",V?"PASS":"FAIL",S);if(!V)exit(3);}
static void Compile(){for(int I=0;I<2;++I){ID3DXBuffer *Code=nullptr,*Error=nullptr,*Asm=nullptr;HRESULT R=D3DXCompileShaderFromFileA("DATA_EXTRA/SHADERS/hyperspace_refraction.hlsl",nullptr,nullptr,I?"PSMain":"VSMain",I?"ps_3_0":"vs_3_0",0,&Code,&Error,nullptr);if(Error){puts((char*)Error->GetBufferPointer());Error->Release();}Check(R);Check(D3DXDisassembleShader((DWORD*)Code->GetBufferPointer(),FALSE,nullptr,&Asm));FILE* F=fopen(I?"src/obj/hyperspace_refraction_check/ps.asm":"src/obj/hyperspace_refraction_check/vs.asm","wb");fwrite(Asm->GetBufferPointer(),1,Asm->GetBufferSize(),F);fclose(F);Asm->Release();if(I)Check(D->CreatePixelShader((DWORD*)Code->GetBufferPointer(),&PS));else Check(D->CreateVertexShader((DWORD*)Code->GetBufferPointer(),&VS));Code->Release();}}
struct Vertex {float P[3];DWORD C;float UV[2];};
static std::vector<DWORD> Render(float Time,float Gain,bool Bars,char const* Name=nullptr){
 D3DLOCKED_RECT Initial;Check(Read->LockRect(&Initial,nullptr,0));for(int Y=0;Y<H;++Y)memcpy((char*)Initial.pBits+Y*Initial.Pitch,Original.data()+Y*W,W*4);Read->UnlockRect();Check(D->UpdateSurface(Read,nullptr,RT,nullptr));
 Check(D->SetRenderTarget(0,RT));D->SetDepthStencilSurface(nullptr);D3DVIEWPORT9 Vp={0,0,W,H,0,1};D->SetViewport(&Vp);Check(D->BeginScene());D->SetVertexShader(VS);D->SetPixelShader(PS);D->SetTexture(0,Scene);D->SetFVF(D3DFVF_XYZ|D3DFVF_DIFFUSE|D3DFVF_TEX1);D->SetRenderState(D3DRS_CULLMODE,D3DCULL_NONE);D->SetRenderState(D3DRS_ZENABLE,FALSE);D->SetRenderState(D3DRS_ZWRITEENABLE,FALSE);D->SetRenderState(D3DRS_ALPHABLENDENABLE,FALSE);D->SetSamplerState(0,D3DSAMP_MINFILTER,D3DTEXF_LINEAR);D->SetSamplerState(0,D3DSAMP_MAGFILTER,D3DTEXF_LINEAR);D->SetSamplerState(0,D3DSAMP_ADDRESSU,D3DTADDRESS_CLAMP);D->SetSamplerState(0,D3DSAMP_ADDRESSV,D3DTADDRESS_CLAMP);
 Vertex Q[]={{{-1,1,0},~0u,{0,0}},{{1,1,0},~0u,{1,0}},{{-1,-1,0},~0u,{0,1}},{{1,-1,0},~0u,{1,1}}};
 float Remap[]={1,1,0,0},P[]={Time,0,1.f/W,1.f/H,.5f/W,.5f/H,1-.5f/W,1-.5f/H};D->SetVertexShaderConstantF(7,Remap,1);D->SetPixelShaderConstantF(0,P,2);Check(D->DrawPrimitiveUP(D3DPT_TRIANGLESTRIP,2,Q,sizeof(Vertex)));
 if(Bars){Remap[0]=.8f;Remap[1]=.6f;P[4]=96.5f/W;P[5]=108.5f/H;P[6]=863.5f/W;P[7]=431.5f/H;}P[1]=Gain;D->SetVertexShaderConstantF(7,Remap,1);D->SetPixelShaderConstantF(0,P,2);Check(D->DrawPrimitiveUP(D3DPT_TRIANGLESTRIP,2,Q,sizeof(Vertex)));Check(D->EndScene());D->SetTexture(0,nullptr);Check(D->GetRenderTargetData(RT,Read));if(Name){char Path[200];sprintf(Path,"src/obj/hyperspace_refraction_check/%s.png",Name);Check(D3DXSaveSurfaceToFileA(Path,D3DXIFF_PNG,Read,nullptr,nullptr));}
 D3DLOCKED_RECT L;Check(Read->LockRect(&L,nullptr,D3DLOCK_READONLY));std::vector<DWORD> Pixels(W*H);for(int Y=0;Y<H;++Y)memcpy(Pixels.data()+Y*W,(char*)L.pBits+Y*L.Pitch,W*4);Read->UnlockRect();return Pixels;}
static int Changes(std::vector<DWORD>const&A,std::vector<DWORD>const&B,int T=0){int N=0;for(size_t I=0;I<A.size();++I){bool Diff=false;for(int C=0;C<3;++C)Diff|=abs(int((A[I]>>(C*8))&255)-int((B[I]>>(C*8))&255))>T;N+=Diff;}return N;}
int main(){CreateDirectoryA("src/obj/hyperspace_refraction_check",nullptr);auto* API=Direct3DCreate9(D3D_SDK_VERSION);Require(API!=nullptr,"D3D9 available");HWND Hwnd=CreateWindowA("STATIC","refraction check",WS_POPUP,0,0,64,64,nullptr,nullptr,GetModuleHandle(nullptr),nullptr);D3DPRESENT_PARAMETERS PP={};PP.Windowed=TRUE;PP.SwapEffect=D3DSWAPEFFECT_DISCARD;PP.BackBufferWidth=64;PP.BackBufferHeight=64;PP.BackBufferFormat=D3DFMT_A8R8G8B8;Check(API->CreateDevice(0,D3DDEVTYPE_HAL,Hwnd,D3DCREATE_HARDWARE_VERTEXPROCESSING,&PP,&D));Compile();Check(D->CreateTexture(W,H,1,0,D3DFMT_A8R8G8B8,D3DPOOL_MANAGED,&Scene,nullptr));Check(D->CreateRenderTarget(W,H,D3DFMT_A8R8G8B8,D3DMULTISAMPLE_NONE,0,FALSE,&RT,nullptr));Check(D->CreateOffscreenPlainSurface(W,H,D3DFMT_A8R8G8B8,D3DPOOL_SYSTEMMEM,&Read,nullptr));D3DLOCKED_RECT L;Check(Scene->LockRect(0,&L,nullptr,0));std::vector<DWORD> Input(W*H);for(int Y=0;Y<H;++Y)for(int X=0;X<W;++X){int C=((X/12+Y/12)&1)?95:35;DWORD Color=D3DCOLOR_XRGB(C,C+8,C+20);if(X>W/2-40&&X<W/2+40&&Y>H/2-65&&Y<H/2+65)Color=0xff9a3020;Input[Y*W+X]=Color;((DWORD*)((char*)L.pBits+Y*L.Pitch))[X]=Color;}Scene->UnlockRect(0);Original=Input;
 auto Base=Render(0,0,false,"base");Require(Changes(Input,Base)==0,"zero gain preserves scene exactly including ship");auto A=Render(3,1,false,"full_scene");Require(Changes(Base,A)>1000,"faint distortion changes patterned scene");Require(Changes(A,Render(3,1,false))==0,"unchanged simulation time freezes effect exactly");Require(Changes(A,Render(3.3f,1,false))>1000,"simulation time advances smooth distortion");Require(Changes(Render(0,1,false),Render(96,1,false),1)<20,"96 second phase wrap is continuous");auto B=Render(3,1,true,"cinematic_viewport");int Leaks=0,Large=0,ShipMoved=0;for(int Y=0;Y<H;++Y)for(int X=0;X<W;++X){int I=Y*W+X;if(X<96||X>=864||Y<108||Y>=432)Leaks+=B[I]!=Base[I];if(X%12>2&&X%12<9&&Y%12>2&&Y%12<9&&(X<W/2-43||X>W/2+43||Y<H/2-68||Y>H/2+68))Large+=A[I]!=Base[I];if(X>W/2-42&&X<W/2+42&&Y>H/2-67&&Y<H/2+67)ShipMoved+=A[I]!=Base[I];}Require(Leaks==0,"cinematic letterbox and pillarbox pixels stay unchanged");Require(Large==0,"refraction cannot reach beyond the promised small displacement neighborhood");Require(ShipMoved>0,"whole scene distortion includes the player ship silhouette");puts("PASS all hyperspace scene-refraction checks");}
